package org.icu.sepsis.sepsis;
import static org.junit.jupiter.api.Assertions.*;import java.nio.file.*;import java.time.*;import java.util.*;import com.fasterxml.jackson.databind.*;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;
class K1ComparisonFileTest {
 @TempDir Path temp;
 final ObjectMapper json=new ObjectMapper().findAndRegisterModules();
 @Test void roundTripProducesSyntheticOnlyComparisonAndProtectsExistingFiles() throws Exception {var helper=new K1WindowComparisonTest();var c=helper.c();c.lactates=List.of(helper.p(3,-12,-11),helper.p(1,0,0));var input=new K1ComparisonFile.Input();input.datasetKind="synthetic";input.cases=List.of(c);input.horizons=List.of(1,3,6);Path source=temp.resolve("input.json"),target=temp.resolve("comparison.json");json.writeValue(source.toFile(),input);K1ComparisonFile.run(source,target);var report=json.readTree(target.toFile());assertEquals(false,report.path("formalQualityUse").asBoolean());assertEquals("synthetic",report.path("datasetKind").asText());assertEquals(3,report.path("assessments").size());assertEquals(1,report.path("assessments").get(2).path("added").size());assertThrows(IllegalArgumentException.class,()->K1ComparisonFile.run(source,target));assertThrows(IllegalArgumentException.class,()->K1ComparisonFile.run(source,source));}
 @Test void malformedOrDuplicateFieldsCannotSilentlyLoad() throws Exception {Path source=temp.resolve("invalid.json"),out=temp.resolve("out.json");Files.writeString(source,"{\"datasetKind\":\"synthetic\",\"datasetKind\":\"authorized_deidentified_history\",\"cases\":[]}");assertThrows(IllegalArgumentException.class,()->K1ComparisonFile.run(source,out));assertFalse(Files.exists(out));Files.writeString(source,"{\"datasetKind\":\"synthetic\",\"cases\":[]} {}");assertThrows(IllegalArgumentException.class,()->K1ComparisonFile.run(source,out));}
 @Test void duplicateRecordConflictAndBadHorizonsCannotBecomeCertain(){var helper=new K1WindowComparisonTest();var c=helper.c();var first=helper.p(1,0,0);var other=helper.p(3,0,0);other.recordId=first.recordId;c.lactates=List.of(first,other);assertNull(K1WindowComparison.evaluate(c,24,6,6).get("value"));assertThrows(IllegalArgumentException.class,()->K1WindowComparison.compare(List.of(c),List.of(12)));}
}
